  3→using Ray.Automerge;
  4→
  5→namespace DemoApp.CollaborativeEditor.Services;
  6→
  7→/// <summary>
  8→/// Wraps <see cref="AutomergeDocument"/> to provide rich text CRDT operations
  9→/// for the collaborative rich text editor demo. Supports text editing, inline
 10→/// marks (bold, italic, underline, link), and block-level structure (paragraphs).
 11→/// </summary>
 12→sealed class AutomergeService : IDisposable
 13→{
 14→  readonly AutomergeDocument _document;
 15→  readonly AutomergeObjectId _textId;
 16→  bool _disposed;
 17→
 18→  public AutomergeService()
 19→  {
 20→    _document = AutomergeDocument.Create();
 21→    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
 22→    _document.Commit("Initialize text field");
 23→  }
 24→
 25→  AutomergeService(AutomergeDocument document, AutomergeObjectId textId)
 26→  {
 27→    _document = document;
 28→    _textId = textId;
 29→  }
 30→
 31→  /// <summary>
 32→  /// Gets the underlying document for sync operations.
 33→  /// </summary>
 34→  public AutomergeDocument Document => _document;
 35→
 36→  /// <summary>
 37→  /// Gets the text object identifier for direct access.
 38→  /// </summary>
 39→  public AutomergeObjectId TextId => _textId;
 40→
 41→  /// <summary>
 42→  /// Gets the current text content of the document.
 43→  /// </summary>
 44→  public string GetText()
 45→  {
 46→    ThrowIfDisposed();
 47→    return _document.GetText(_textId);
 48→  }
 49→
 50→  /// <summary>
 51→  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
 52→  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
 53→  /// </summary>
 54→  public void SpliceText(ulong index, long deleteCount, string insertText)
 55→  {
 56→    ThrowIfDisposed();
 57→    _document.SpliceText(_textId, index, deleteCount, insertText);
 58→    _document.Commit($"Edit at {index}");
 59→  }
 60→
 61→  /// <summary>
 62→  /// Applies or removes a bold mark on the specified range.
 63→  /// </summary>
 64→  public void MarkBold(ulong start, ulong end, bool value)
 65→  {
 66→    ThrowIfDisposed();
 67→    _document.Mark(_textId, start, end, "bold", value, ExpandMode.Both);
 68→    _document.Commit("Mark bold");
 69→  }
 70→
 71→  /// <summary>
 72→  /// Removes the bold mark from the specified range.
 73→  /// </summary>
 74→  public void UnmarkBold(ulong start, ulong end)
 75→  {
 76→    ThrowIfDisposed();
 77→    _document.Unmark(_textId, "bold", start, end, ExpandMode.Both);
 78→    _document.Commit("Unmark bold");
 79→  }
 80→
 81→  /// <summary>
 82→  /// Applies or removes an italic mark on the specified range.
 83→  /// </summary>
 84→  public void MarkItalic(ulong start, ulong end, bool value)
 85→  {
 86→    ThrowIfDisposed();
 87→    _document.Mark(_textId, start, end, "italic", value, ExpandMode.Both);
 88→    _document.Commit("Mark italic");
 89→  }
 90→
 91→  /// <summary>
 92→  /// Removes the italic mark from the specified range.
 93→  /// </summary>
 94→  public void UnmarkItalic(ulong start, ulong end)
 95→  {
 96→    ThrowIfDisposed();
 97→    _document.Unmark(_textId, "italic", start, end, ExpandMode.Both);
 98→    _document.Commit("Unmark italic");
 99→  }
100→
101→  /// <summary>
102→  /// Applies or removes an underline mark on the specified range.
103→  /// </summary>
104→  public void MarkUnderline(ulong start, ulong end, bool value)
105→  {
106→    ThrowIfDisposed();
107→    _document.Mark(_textId, start, end, "underline", value, ExpandMode.Both);
108→    _document.Commit("Mark underline");
109→  }
110→
111→  /// <summary>
112→  /// Removes the underline mark from the specified range.
113→  /// </summary>
114→  public void UnmarkUnderline(ulong start, ulong end)
115→  {
116→    ThrowIfDisposed();
117→    _document.Unmark(_textId, "underline", start, end, ExpandMode.Both);
118→    _document.Commit("Unmark underline");
119→  }
120→
121→  /// <summary>
122→  /// Applies a link mark with the specified URL on the given range.
123→  /// </summary>
124→  public void MarkLink(ulong start, ulong end, string url)
125→  {
126→    ThrowIfDisposed();
127→    _document.Mark(_textId, start, end, "link", url, ExpandMode.None);
128→    _document.Commit("Mark link");
129→  }
130→
131→  /// <summary>
132→  /// Removes the link mark from the specified range.
133→  /// </summary>
134→  public void UnmarkLink(ulong start, ulong end)
135→  {
136→    ThrowIfDisposed();
137→    _document.Unmark(_textId, "link", start, end, ExpandMode.None);
138→    _document.Commit("Unmark link");
139→  }
140→
141→  /// <summary>
142→  /// Gets all marks applied to the text.
143→  /// </summary>
144→  public IReadOnlyList<AutomergeMarkInfo> GetMarks()
145→  {
146→    ThrowIfDisposed();
147→    return _document.GetMarks(_textId);
148→  }
149→
150→  /// <summary>
151→  /// Gets the text content segmented by marks and blocks.
152→  /// </summary>
153→  public IReadOnlyList<AutomergeSpan> GetSpans()
154→  {
155→    ThrowIfDisposed();
156→    return _document.GetSpans(_textId);
157→  }
158→
159→  /// <summary>
160→  /// Inserts a block marker at the given index, splitting the text.
161→  /// Sets the block type to <paramref name="blockType"/>.
162→  /// </summary>
163→  public void SplitBlock(ulong index, string blockType)
164→  {
165→    ThrowIfDisposed();
166→    AutomergeObjectId blockId = _document.SplitBlock(_textId, index);
167→    _document.PutString(blockId, "type", blockType);
168→    _document.Commit($"Split block at {index}");
169→  }
170→
171→  /// <summary>
172→  /// Removes a block marker at the given index, joining adjacent text.
173→  /// </summary>
174→  public void JoinBlock(ulong index)
175→  {
176→    ThrowIfDisposed();
177→    _document.JoinBlock(_textId, index);
178→    _document.Commit($"Join block at {index}");
179→  }
180→
181→  /// <summary>
182→  /// Atomically updates the span list with minimal diff.
183→  /// </summary>
184→  public void UpdateSpans(IReadOnlyList<AutomergeSpan> spans)
185→  {
186→    ThrowIfDisposed();
187→    _document.UpdateSpans(_textId, spans);
188→    _document.Commit("Update spans");
189→  }
190→
191→  /// <summary>
192→  /// Gets a stable cursor at the given index.
193→  /// </summary>
194→  public AutomergeCursor GetCursor(ulong index)
195→  {
196→    ThrowIfDisposed();
197→    return _document.GetCursor(_textId, index);
198→  }
199→
200→  /// <summary>
201→  /// Resolves a cursor to its current index position.
202→  /// </summary>
203→  public ulong GetCursorPosition(AutomergeCursor cursor)
204→  {
205→    ThrowIfDisposed();
206→    return _document.GetCursorPosition(_textId, cursor);
207→  }
208→
209→  /// <summary>
210→  /// Saves the full document state as a byte array.
211→  /// </summary>
212→  public byte[] Save()
213→  {
214→    ThrowIfDisposed();
215→    return _document.Save();
216→  }
217→
218→  /// <summary>
219→  /// Creates a peer service by forking the current document. The forked service
220→  /// shares the same text object ID and history, enabling true collaborative sync.
221→  /// </summary>
222→  public AutomergeService Fork()
223→  {
224→    ThrowIfDisposed();
225→    AutomergeDocument forked = _document.Fork();
226→    return new AutomergeService(forked, _textId);
227→  }
228→
229→  /// <summary>
230→  /// Loads a document from a previously saved byte array.
231→  /// </summary>
232→  public static AutomergeService Load(byte[] data)
233→  {
234→    AutomergeDocument doc = AutomergeDocument.Load(data);
235→    List<string> keys = doc.GetKeys(doc.RootId).ToList();
236→    if(!keys.Contains("content"))
237→    {
238→      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
239→    }
240→
241→    AutomergeObjectId textId = doc.GetObject(doc.RootId, "content")
242→      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
243→
244→    return new AutomergeService(doc, textId);
245→  }
246→
247→  public void Dispose()
248→  {
249→    if(!_disposed)
250→    {
251→      _disposed = true;
252→      _document.Dispose();
253→    }
254→  }
255→
256→  void ThrowIfDisposed()
257→  {
258→    ObjectDisposedException.ThrowIf(_disposed, this);
259→  }
260→}
