  3→using System.Reactive;
  4→using Avalonia.Threading;
  5→using DemoApp.CollaborativeEditor.Models;
  6→using DemoApp.CollaborativeEditor.Services;
  7→using ReactiveUI;
  8→
  9→namespace DemoApp.CollaborativeEditor.ViewModels;
 10→
 11→public class EditorViewModel : ViewModelBase, IDisposable
 12→{
 13→  readonly AutomergeService _localService;
 14→  readonly SyncService _syncService;
 15→  string _documentText = string.Empty;
 16→  string _peerText = string.Empty;
 17→  string _syncStatus = "Disconnected";
 18→  int _peerCount;
 19→  int _cursorPosition;
 20→  int _selectionLength;
 21→  bool _isBold;
 22→  bool _isItalic;
 23→  bool _isUnderline;
 24→  bool _disposed;
 25→
 26→  public EditorViewModel()
 27→  {
 28→    _localService = new AutomergeService();
 29→    AutomergeService peerService = _localService.Fork();
 30→    _syncService = new SyncService(_localService, peerService);
 31→
 32→    _syncService.SyncCompleted += OnSyncCompleted;
 33→    _syncService.PeerEdited += OnPeerEdited;
 34→
 35→    SimulatePeerEditCommand = ReactiveCommand.Create(SimulatePeerEdit);
 36→    SaveCommand = ReactiveCommand.Create(SaveDocument);
 37→    ToggleSyncCommand = ReactiveCommand.Create(ToggleSync);
 38→    ToggleBoldCommand = ReactiveCommand.Create(ToggleBold);
 39→    ToggleItalicCommand = ReactiveCommand.Create(ToggleItalic);
 40→    ToggleUnderlineCommand = ReactiveCommand.Create(ToggleUnderline);
 41→
 42→    _syncService.Start();
 43→    PeerCount = _syncService.PeerCount;
 44→    SyncStatus = "Connected";
 45→  }
 46→
 47→  /// <summary>
 48→  /// The current text content of the local Automerge document.
 49→  /// Two-way bound to the TextBox in the view.
 50→  /// </summary>
 51→  public string DocumentText
 52→  {
 53→    get => _documentText;
 54→    set
 55→    {
 56→      if(_documentText == value)
 57→      {
 58→        return;
 59→      }
 60→
 61→      ApplyTextChange(value);
 62→      this.RaiseAndSetIfChanged(ref _documentText, value);
 63→    }
 64→  }
 65→
 66→  /// <summary>
 67→  /// The current text content of the peer document (read-only display).
 68→  /// </summary>
 69→  public string PeerText
 70→  {
 71→    get => _peerText;
 72→    set => this.RaiseAndSetIfChanged(ref _peerText, value);
 73→  }
 74→
 75→  /// <summary>
 76→  /// Current sync status description.
 77→  /// </summary>
 78→  public string SyncStatus
 79→  {
 80→    get => _syncStatus;
 81→    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
 82→  }
 83→
 84→  /// <summary>
 85→  /// Number of connected peers.
 86→  /// </summary>
 87→  public int PeerCount
 88→  {
 89→    get => _peerCount;
 90→    set => this.RaiseAndSetIfChanged(ref _peerCount, value);
 91→  }
 92→
 93→  /// <summary>
 94→  /// Current cursor position in the local document.
 95→  /// </summary>
 96→  public int CursorPosition
 97→  {
 98→    get => _cursorPosition;
 99→    set
100→    {
101→      this.RaiseAndSetIfChanged(ref _cursorPosition, value);
102→      UpdateFormattingState();
103→    }
104→  }
105→
106→  /// <summary>
107→  /// Length of the current text selection.
108→  /// </summary>
109→  public int SelectionLength
110→  {
111→    get => _selectionLength;
112→    set => this.RaiseAndSetIfChanged(ref _selectionLength, value);
113→  }
114→
115→  /// <summary>
116→  /// Whether bold formatting is active at the cursor.
117→  /// </summary>
118→  public bool IsBold
119→  {
120→    get => _isBold;
121→    set => this.RaiseAndSetIfChanged(ref _isBold, value);
122→  }
123→
124→  /// <summary>
125→  /// Whether italic formatting is active at the cursor.
126→  /// </summary>
127→  public bool IsItalic
128→  {
129→    get => _isItalic;
130→    set => this.RaiseAndSetIfChanged(ref _isItalic, value);
131→  }
132→
133→  /// <summary>
134→  /// Whether underline formatting is active at the cursor.
135→  /// </summary>
136→  public bool IsUnderline
137→  {
138→    get => _isUnderline;
139→    set => this.RaiseAndSetIfChanged(ref _isUnderline, value);
140→  }
141→
142→  public ReactiveCommand<Unit, Unit> SimulatePeerEditCommand { get; }
143→
144→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
145→
146→  public ReactiveCommand<Unit, Unit> ToggleSyncCommand { get; }
147→
148→  public ReactiveCommand<Unit, Unit> ToggleBoldCommand { get; }
149→
150→  public ReactiveCommand<Unit, Unit> ToggleItalicCommand { get; }
151→
152→  public ReactiveCommand<Unit, Unit> ToggleUnderlineCommand { get; }
153→
154→  void ApplyTextChange(string newText)
155→  {
156→    string currentText = _localService.GetText();
157→
158→    // Find the difference and apply as a splice operation.
159→    // This is a simplified diff: find common prefix and suffix.
160→    int prefixLen = 0;
161→    int minLen = Math.Min(currentText.Length, newText.Length);
162→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
163→    {
164→      prefixLen++;
165→    }
166→
167→    int suffixLen = 0;
168→    int maxSuffix = minLen - prefixLen;
169→    while(suffixLen < maxSuffix
170→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
171→    {
172→      suffixLen++;
173→    }
174→
175→    int deleteCount = currentText.Length - prefixLen - suffixLen;
176→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
177→
178→    if(deleteCount > 0 || insertText.Length > 0)
179→    {
180→      _localService.SpliceText((ulong)prefixLen, deleteCount, insertText);
181→    }
182→  }
183→
184→  void ToggleBold()
185→  {
186→    if(_selectionLength <= 0)
187→    {
188→      return;
189→    }
190→
191→    ulong start = (ulong)_cursorPosition;
192→    ulong end = (ulong)(_cursorPosition + _selectionLength);
193→
194→    if(_isBold)
195→    {
196→      _localService.UnmarkBold(start, end);
197→    }
198→    else
199→    {
200→      _localService.MarkBold(start, end, true);
201→    }
202→
203→    UpdateFormattingState();
204→  }
205→
206→  void ToggleItalic()
207→  {
208→    if(_selectionLength <= 0)
209→    {
210→      return;
211→    }
212→
213→    ulong start = (ulong)_cursorPosition;
214→    ulong end = (ulong)(_cursorPosition + _selectionLength);
215→
216→    if(_isItalic)
217→    {
218→      _localService.UnmarkItalic(start, end);
219→    }
220→    else
221→    {
222→      _localService.MarkItalic(start, end, true);
223→    }
224→
225→    UpdateFormattingState();
226→  }
227→
228→  void ToggleUnderline()
229→  {
230→    if(_selectionLength <= 0)
231→    {
232→      return;
233→    }
234→
235→    ulong start = (ulong)_cursorPosition;
236→    ulong end = (ulong)(_cursorPosition + _selectionLength);
237→
238→    if(_isUnderline)
239→    {
240→      _localService.UnmarkUnderline(start, end);
241→    }
242→    else
243→    {
244→      _localService.MarkUnderline(start, end, true);
245→    }
246→
247→    UpdateFormattingState();
248→  }
249→
250→  void UpdateFormattingState()
251→  {
252→    if(_disposed)
253→    {
254→      return;
255→    }
256→
257→    var marks = _localService.GetMarks();
258→    FormattingState state = FormattingState.FromMarks(marks, (ulong)_cursorPosition);
259→    IsBold = state.IsBold;
260→    IsItalic = state.IsItalic;
261→    IsUnderline = state.IsUnderline;
262→  }
263→
264→  void SimulatePeerEdit()
265→  {
266→    string peerText = _syncService.GetPeerText();
267→    string timestamp = DateTime.Now.ToString("HH:mm:ss");
268→    string edit = $"[Peer @ {timestamp}] ";
269→    _syncService.SimulatePeerEdit(edit, (ulong)peerText.Length);
270→
271→    _syncService.RunSyncRound();
272→    RefreshFromDocument();
273→  }
274→
275→  void SaveDocument()
276→  {
277→    byte[] saved = _localService.Save();
278→    SyncStatus = $"Saved ({saved.Length} bytes)";
279→  }
280→
281→  void ToggleSync()
282→  {
283→    if(_syncService.IsRunning)
284→    {
285→      _syncService.Stop();
286→      SyncStatus = "Paused";
287→    }
288→    else
289→    {
290→      _syncService.Start();
291→      SyncStatus = "Connected";
292→    }
293→  }
294→
295→  void OnSyncCompleted()
296→  {
297→    Dispatcher.UIThread.Post(RefreshFromDocument);
298→  }
299→
300→  void OnPeerEdited()
301→  {
