 10→namespace Microsoft.Extensions.Hosting;
 11→
 12→// Adds common Aspire services: service discovery, resilience, health checks, and OpenTelemetry.
 13→// This project should be referenced by each service project in your solution.
 14→// To learn more about using this project, see https://aka.ms/dotnet/aspire/service-defaults
 15→public static class Extensions
 16→{
 17→  private const string HealthEndpointPath = "/health";
 18→  private const string AlivenessEndpointPath = "/alive";
 19→
 20→  public static TBuilder AddServiceDefaults<TBuilder>(this TBuilder builder) where TBuilder : IHostApplicationBuilder
 21→  {
 22→    builder.ConfigureOpenTelemetry();
 23→
 24→    builder.AddDefaultHealthChecks();
 25→
 26→    builder.Services.AddServiceDiscovery();
 27→
 28→    builder.Services.ConfigureHttpClientDefaults(http =>
 29→    {
 30→      // Turn on resilience by default
 31→      http.AddStandardResilienceHandler();
 32→
 33→      // Turn on service discovery by default
 34→      http.AddServiceDiscovery();
 35→    });
 36→
 37→    // Uncomment the following to restrict the allowed schemes for service discovery.
 38→    // builder.Services.Configure<ServiceDiscoveryOptions>(options =>
 39→    // {
 40→    //     options.AllowedSchemes = ["https"];
 41→    // });
 42→
 43→    return builder;
 44→  }
 45→
 46→  public static TBuilder ConfigureOpenTelemetry<TBuilder>(this TBuilder builder)
 47→    where TBuilder : IHostApplicationBuilder
 48→  {
 49→    builder.Logging.AddOpenTelemetry(logging =>
 50→    {
 51→      logging.IncludeFormattedMessage = true;
 52→      logging.IncludeScopes = true;
 53→    });
 54→
 55→    builder.Services.AddOpenTelemetry()
 56→      .WithMetrics(metrics =>
 57→      {
 58→        metrics.AddAspNetCoreInstrumentation()
 59→          .AddHttpClientInstrumentation()
 60→          .AddRuntimeInstrumentation()
 61→          .AddMeter("Microsoft.Orleans");
 62→      })
 63→      .WithTracing(tracing =>
 64→      {
 65→        tracing.AddSource("Microsoft.Orleans.Runtime");
 66→        tracing.AddSource("Microsoft.Orleans.Application");
 67→        
 68→        tracing.AddSource(builder.Environment.ApplicationName)
 69→          .AddAspNetCoreInstrumentation(tracing =>
 70→            // Exclude health check requests from tracing
 71→            tracing.Filter = context =>
 72→              !context.Request.Path.StartsWithSegments(HealthEndpointPath)
 73→              && !context.Request.Path.StartsWithSegments(AlivenessEndpointPath)
 74→          )
 75→          // Uncomment the following line to enable gRPC instrumentation (requires the OpenTelemetry.Instrumentation.GrpcNetClient package)
 76→          //.AddGrpcClientInstrumentation()
 77→          .AddHttpClientInstrumentation();
 78→      });
 79→
 80→    builder.AddOpenTelemetryExporters();
 81→
 82→    return builder;
 83→  }
 84→
 85→  private static TBuilder AddOpenTelemetryExporters<TBuilder>(this TBuilder builder)
 86→    where TBuilder : IHostApplicationBuilder
 87→  {
 88→    var useOtlpExporter = !string.IsNullOrWhiteSpace(builder.Configuration["OTEL_EXPORTER_OTLP_ENDPOINT"]);
 89→
 90→    if(useOtlpExporter)
 91→    {
 92→      builder.Services.AddOpenTelemetry().UseOtlpExporter();
 93→    }
 94→
 95→    // Uncomment the following lines to enable the Azure Monitor exporter (requires the Azure.Monitor.OpenTelemetry.AspNetCore package)
 96→    //if (!string.IsNullOrEmpty(builder.Configuration["APPLICATIONINSIGHTS_CONNECTION_STRING"]))
 97→    //{
 98→    //    builder.Services.AddOpenTelemetry()
 99→    //       .UseAzureMonitor();
100→    //}
101→
102→    return builder;
103→  }
104→
105→  public static TBuilder AddDefaultHealthChecks<TBuilder>(this TBuilder builder)
106→    where TBuilder : IHostApplicationBuilder
107→  {
108→    builder.Services.AddHealthChecks()
109→      // Add a default liveness check to ensure app is responsive
110→      .AddCheck("self", () => HealthCheckResult.Healthy(), ["live"]);
111→
112→    return builder;
113→  }
114→
115→  public static WebApplication MapDefaultEndpoints(this WebApplication app)
116→  {
117→    // Adding health checks endpoints to applications in non-development environments has security implications.
118→    // See https://aka.ms/dotnet/aspire/healthchecks for details before enabling these endpoints in non-development environments.
119→    if(app.Environment.IsDevelopment())
120→    {
121→      // All health checks must pass for app to be considered ready to accept traffic after starting
122→      app.MapHealthChecks(HealthEndpointPath);
123→
124→      // Only health checks tagged with the "live" tag must pass for app to be considered alive
125→      app.MapHealthChecks(AlivenessEndpointPath, new HealthCheckOptions { Predicate = r => r.Tags.Contains("live") });
126→    }
127→
128→    return app;
129→  }
130→}

