 6→
 7→/// <summary>
 8→/// Tracks which formatting marks are active at the current cursor position.
 9→/// Used to drive toolbar button states (pressed/unpressed) in the editor.
10→/// </summary>
11→sealed class FormattingState
12→{
13→  /// <summary>
14→  /// Gets or sets whether bold formatting is active at the cursor.
15→  /// </summary>
16→  public bool IsBold { get; set; }
17→
18→  /// <summary>
19→  /// Gets or sets whether italic formatting is active at the cursor.
20→  /// </summary>
21→  public bool IsItalic { get; set; }
22→
23→  /// <summary>
24→  /// Gets or sets whether underline formatting is active at the cursor.
25→  /// </summary>
26→  public bool IsUnderline { get; set; }
27→
28→  /// <summary>
29→  /// Gets or sets the link URL if the cursor is within a link mark, or null otherwise.
30→  /// </summary>
31→  public string? LinkUrl { get; set; }
32→
33→  /// <summary>
34→  /// Gets whether the cursor is within a link mark.
35→  /// </summary>
36→  public bool HasLink => LinkUrl is not null;
37→
38→  /// <summary>
39→  /// Creates a <see cref="FormattingState"/> from the document marks at the given cursor position.
40→  /// A mark is considered active if <paramref name="cursorPosition"/> falls within
41→  /// its range [start, end).
42→  /// </summary>
43→  public static FormattingState FromMarks(IReadOnlyList<AutomergeMarkInfo> marks, ulong cursorPosition)
44→  {
45→    var state = new FormattingState();
46→
47→    foreach(AutomergeMarkInfo mark in marks)
48→    {
49→      if(cursorPosition < mark.Start || cursorPosition >= mark.End)
50→      {
51→        continue;
52→      }
53→
54→      switch(mark.Name)
55→      {
56→        case "bold":
57→          state.IsBold = true;
58→          break;
59→        case "italic":
60→          state.IsItalic = true;
61→          break;
62→        case "underline":
63→          state.IsUnderline = true;
64→          break;
65→        case "link":
66→          state.LinkUrl = mark.Value.StringValue;
67→          break;
68→      }
69→    }
70→
71→    return state;
72→  }
73→}
