  7→/// <summary>
  8→/// Wraps <see cref="AutomergeDocument"/> to provide text CRDT operations
  9→/// for the collaborative text editor demo.
 10→/// </summary>
 11→sealed class AutomergeService : IDisposable
 12→{
 13→  readonly AutomergeDocument _document;
 14→  readonly AutomergeObjectId _textId;
 15→  bool _disposed;
 16→
 17→  public AutomergeService()
 18→  {
 19→    _document = AutomergeDocument.Create();
 20→    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
 21→    _document.Commit("Initialize text field");
 22→  }
 23→
 24→  AutomergeService(AutomergeDocument document, AutomergeObjectId textId)
 25→  {
 26→    _document = document;
 27→    _textId = textId;
 28→  }
 29→
 30→  /// <summary>
 31→  /// Gets the underlying document for sync operations.
 32→  /// </summary>
 33→  public AutomergeDocument Document => _document;
 34→
 35→  /// <summary>
 36→  /// Gets the text object identifier for cursor operations.
 37→  /// </summary>
 38→  public AutomergeObjectId TextId => _textId;
 39→
 40→  /// <summary>
 41→  /// Gets the current text content of the document.
 42→  /// </summary>
 43→  public string GetText()
 44→  {
 45→    ThrowIfDisposed();
 46→    return _document.GetText(_textId);
 47→  }
 48→
 49→  /// <summary>
 50→  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
 51→  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
 52→  /// </summary>
 53→  public void SpliceText(ulong index, long deleteCount, string insertText)
 54→  {
 55→    ThrowIfDisposed();
 56→    _document.SpliceText(_textId, index, deleteCount, insertText);
 57→    _document.Commit($"Edit at {index}");
 58→  }
 59→
 60→  /// <summary>
 61→  /// Gets a stable cursor at the given index. Cursors track logical positions
 62→  /// even as concurrent edits shift indices.
 63→  /// </summary>
 64→  public AutomergeCursor GetCursor(ulong index)
 65→  {
 66→    ThrowIfDisposed();
 67→    return _document.GetCursor(_textId, index);
 68→  }
 69→
 70→  /// <summary>
 71→  /// Resolves a cursor to its current index position.
 72→  /// </summary>
 73→  public ulong GetCursorPosition(AutomergeCursor cursor)
 74→  {
 75→    ThrowIfDisposed();
 76→    return _document.GetCursorPosition(_textId, cursor);
 77→  }
 78→
 79→  /// <summary>
 80→  /// Saves the full document state as a byte array.
 81→  /// </summary>
 82→  public byte[] Save()
 83→  {
 84→    ThrowIfDisposed();
 85→    return _document.Save();
 86→  }
 87→
 88→  /// <summary>
 89→  /// Loads a document from a previously saved byte array.
 90→  /// </summary>
 91→  public static AutomergeService Load(byte[] data)
 92→  {
 93→    var doc = AutomergeDocument.Load(data);
 94→    var keys = doc.GetKeys(doc.RootId).ToList();
 95→    if(!keys.Contains("content"))
 96→    {
 97→      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
 98→    }
 99→
100→    var textId = doc.GetObject(doc.RootId, "content")
101→      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
102→
103→    return new AutomergeService(doc, textId);
104→  }
105→
106→  public void Dispose()
107→  {
108→    if(!_disposed)
109→    {
110→      _disposed = true;
111→      _document.Dispose();
112→    }
113→  }
114→
115→  void ThrowIfDisposed()
116→  {
117→    ObjectDisposedException.ThrowIf(_disposed, this);
118→  }
119→}
