  3→using System.Timers;
  4→using Ray.Automerge;
  5→using Timer = System.Timers.Timer;
  6→
  7→namespace DemoApp.CollaborativeTextEditor.Services;
  8→
  9→/// <summary>
 10→/// Manages sync state between the local document and a simulated peer document.
 11→/// Uses the Automerge sync protocol (GenerateSyncMessage / ReceiveSyncMessage)
 12→/// on a periodic timer to demonstrate real-time collaborative synchronization.
 13→/// </summary>
 14→sealed class SyncService : IDisposable
 15→{
 16→  readonly AutomergeService _local;
 17→  readonly AutomergeService _peer;
 18→  readonly AutomergeSyncState _syncLocalToPeer;
 19→  readonly AutomergeSyncState _syncPeerToLocal;
 20→  readonly Timer _syncTimer;
 21→  readonly object _syncLock = new();
 22→  bool _disposed;
 23→
 24→  /// <summary>
 25→  /// Fired after a sync round completes, on the timer thread.
 26→  /// </summary>
 27→  public event Action? SyncCompleted;
 28→
 29→  /// <summary>
 30→  /// Fired when the peer makes a simulated edit, on the timer thread.
 31→  /// </summary>
 32→  public event Action? PeerEdited;
 33→
 34→  public SyncService(AutomergeService local, AutomergeService peer)
 35→  {
 36→    _local = local;
 37→    _peer = peer;
 38→
 39→    _syncLocalToPeer = _local.Document.CreateSyncState();
 40→    _syncPeerToLocal = _peer.Document.CreateSyncState();
 41→
 42→    _syncTimer = new Timer(500);
 43→    _syncTimer.Elapsed += OnSyncTimerElapsed;
 44→    _syncTimer.AutoReset = true;
 45→  }
 46→
 47→  /// <summary>
 48→  /// Gets the number of connected peers (always 1 in this demo).
 49→  /// </summary>
 50→  public int PeerCount => 1;
 51→
 52→  /// <summary>
 53→  /// Gets whether the sync service is actively running.
 54→  /// </summary>
 55→  public bool IsRunning => _syncTimer.Enabled;
 56→
 57→  /// <summary>
 58→  /// Gets the text content of the simulated peer document.
 59→  /// </summary>
 60→  public string GetPeerText()
 61→  {
 62→    lock(_syncLock)
 63→    {
 64→      return _peer.GetText();
 65→    }
 66→  }
 67→
 68→  /// <summary>
 69→  /// Starts periodic synchronization between local and peer documents.
 70→  /// </summary>
 71→  public void Start()
 72→  {
 73→    ThrowIfDisposed();
 74→    RunSyncRound();
 75→    _syncTimer.Start();
 76→  }
 77→
 78→  /// <summary>
 79→  /// Stops periodic synchronization.
 80→  /// </summary>
 81→  public void Stop()
 82→  {
 83→    _syncTimer.Stop();
 84→  }
 85→
 86→  /// <summary>
 87→  /// Simulates a remote peer editing the document concurrently.
 88→  /// </summary>
 89→  public void SimulatePeerEdit(string text, ulong index)
 90→  {
 91→    ThrowIfDisposed();
 92→    lock(_syncLock)
 93→    {
 94→      _peer.SpliceText(index, 0, text);
 95→    }
 96→
 97→    PeerEdited?.Invoke();
 98→  }
 99→
100→  /// <summary>
101→  /// Runs one round of bidirectional sync (local to peer, peer to local).
102→  /// Returns true if any messages were exchanged.
103→  /// </summary>
104→  public bool RunSyncRound()
105→  {
106→    lock(_syncLock)
107→    {
108→      bool exchanged = false;
109→
110→      for(int i = 0; i < 10; i++)
111→      {
112→        var msgLocalToPeer = _local.Document.GenerateSyncMessage(_syncLocalToPeer);
113→        var msgPeerToLocal = _peer.Document.GenerateSyncMessage(_syncPeerToLocal);
114→
115→        if(msgLocalToPeer is null && msgPeerToLocal is null)
116→        {
117→          break;
118→        }
119→
120→        if(msgLocalToPeer is not null)
121→        {
122→          _peer.Document.ReceiveSyncMessage(_syncPeerToLocal, msgLocalToPeer);
123→          exchanged = true;
124→        }
125→
126→        if(msgPeerToLocal is not null)
127→        {
128→          _local.Document.ReceiveSyncMessage(_syncLocalToPeer, msgPeerToLocal);
129→          exchanged = true;
130→        }
131→      }
132→
133→      return exchanged;
134→    }
135→  }
136→
137→  void OnSyncTimerElapsed(object? sender, ElapsedEventArgs e)
138→  {
139→    if(_disposed)
140→    {
141→      return;
142→    }
143→
144→    bool exchanged = RunSyncRound();
145→    if(exchanged)
146→    {
147→      SyncCompleted?.Invoke();
148→    }
149→  }
150→
151→  public void Dispose()
152→  {
153→    if(!_disposed)
154→    {
155→      _disposed = true;
156→      _syncTimer.Stop();
157→      _syncTimer.Dispose();
158→      _syncLocalToPeer.Dispose();
159→      _syncPeerToLocal.Dispose();
160→      _peer.Dispose();
161→    }
162→  }
163→
164→  void ThrowIfDisposed()
165→  {
166→    ObjectDisposedException.ThrowIf(_disposed, this);
167→  }
168→}
