  9→namespace DemoApp.CollaborativeTextEditor.ViewModels;
 10→
 11→public class TextEditorViewModel : ViewModelBase, IDisposable
 12→{
 13→  readonly AutomergeService _localService;
 14→  readonly AutomergeService _peerService;
 15→  readonly SyncService _syncService;
 16→  string _documentText = string.Empty;
 17→  string _peerText = string.Empty;
 18→  string _syncStatus = "Disconnected";
 19→  int _peerCount;
 20→  int _cursorPosition;
 21→  bool _disposed;
 22→
 23→  public TextEditorViewModel()
 24→  {
 25→    _localService = new AutomergeService();
 26→    _peerService = new AutomergeService();
 27→    _syncService = new SyncService(_localService, _peerService);
 28→
 29→    _syncService.SyncCompleted += OnSyncCompleted;
 30→    _syncService.PeerEdited += OnPeerEdited;
 31→
 32→    SimulatePeerEditCommand = ReactiveCommand.Create(SimulatePeerEdit);
 33→    SaveCommand = ReactiveCommand.Create(SaveDocument);
 34→    ToggleSyncCommand = ReactiveCommand.Create(ToggleSync);
 35→
 36→    _syncService.Start();
 37→    PeerCount = _syncService.PeerCount;
 38→    SyncStatus = "Connected";
 39→  }
 40→
 41→  /// <summary>
 42→  /// The current text content of the local Automerge document.
 43→  /// Two-way bound to the TextBox in the view.
 44→  /// </summary>
 45→  public string DocumentText
 46→  {
 47→    get => _documentText;
 48→    set
 49→    {
 50→      if(_documentText == value)
 51→      {
 52→        return;
 53→      }
 54→
 55→      ApplyTextChange(value);
 56→      this.RaiseAndSetIfChanged(ref _documentText, value);
 57→    }
 58→  }
 59→
 60→  /// <summary>
 61→  /// The current text content of the peer document (read-only display).
 62→  /// </summary>
 63→  public string PeerText
 64→  {
 65→    get => _peerText;
 66→    set => this.RaiseAndSetIfChanged(ref _peerText, value);
 67→  }
 68→
 69→  /// <summary>
 70→  /// Current sync status description.
 71→  /// </summary>
 72→  public string SyncStatus
 73→  {
 74→    get => _syncStatus;
 75→    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
 76→  }
 77→
 78→  /// <summary>
 79→  /// Number of connected peers.
 80→  /// </summary>
 81→  public int PeerCount
 82→  {
 83→    get => _peerCount;
 84→    set => this.RaiseAndSetIfChanged(ref _peerCount, value);
 85→  }
 86→
 87→  /// <summary>
 88→  /// Current cursor position in the local document.
 89→  /// </summary>
 90→  public int CursorPosition
 91→  {
 92→    get => _cursorPosition;
 93→    set => this.RaiseAndSetIfChanged(ref _cursorPosition, value);
 94→  }
 95→
 96→  public ReactiveCommand<Unit, Unit> SimulatePeerEditCommand { get; }
 97→
 98→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
 99→
100→  public ReactiveCommand<Unit, Unit> ToggleSyncCommand { get; }
101→
102→  void ApplyTextChange(string newText)
103→  {
104→    string currentText = _localService.GetText();
105→
106→    // Find the difference and apply as a splice operation.
107→    // This is a simplified diff: find common prefix and suffix.
108→    int prefixLen = 0;
109→    int minLen = Math.Min(currentText.Length, newText.Length);
110→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
111→    {
112→      prefixLen++;
113→    }
114→
115→    int suffixLen = 0;
116→    int maxSuffix = minLen - prefixLen;
117→    while(suffixLen < maxSuffix
118→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
119→    {
120→      suffixLen++;
121→    }
122→
123→    int deleteCount = currentText.Length - prefixLen - suffixLen;
124→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
125→
126→    if(deleteCount > 0 || insertText.Length > 0)
127→    {
128→      _localService.SpliceText((ulong)prefixLen, deleteCount, insertText);
129→    }
130→  }
131→
132→  void SimulatePeerEdit()
133→  {
134→    string peerText = _syncService.GetPeerText();
135→    string timestamp = DateTime.Now.ToString("HH:mm:ss");
136→    string edit = $"[Peer @ {timestamp}] ";
137→    _syncService.SimulatePeerEdit(edit, (ulong)peerText.Length);
138→
139→    // Force an immediate sync round so the local side picks up the edit.
140→    _syncService.RunSyncRound();
141→    RefreshFromDocument();
142→  }
143→
144→  void SaveDocument()
145→  {
146→    byte[] saved = _localService.Save();
147→    SyncStatus = $"Saved ({saved.Length} bytes)";
148→  }
149→
150→  void ToggleSync()
151→  {
152→    if(_syncService.IsRunning)
153→    {
154→      _syncService.Stop();
155→      SyncStatus = "Paused";
156→    }
157→    else
158→    {
159→      _syncService.Start();
160→      SyncStatus = "Connected";
161→    }
162→  }
163→
164→  void OnSyncCompleted()
165→  {
166→    Dispatcher.UIThread.Post(RefreshFromDocument);
167→  }
168→
169→  void OnPeerEdited()
170→  {
171→    Dispatcher.UIThread.Post(() => PeerText = _syncService.GetPeerText());
172→  }
173→
174→  void RefreshFromDocument()
175→  {
176→    string text = _localService.GetText();
177→    if(_documentText != text)
178→    {
179→      _documentText = text;
180→      this.RaisePropertyChanged(nameof(DocumentText));
181→    }
182→
183→    PeerText = _syncService.GetPeerText();
184→  }
185→
186→  public void Dispose()
187→  {
188→    if(!_disposed)
189→    {
190→      _disposed = true;
191→      _syncService.Dispose();
192→      _localService.Dispose();
193→    }
194→  }
195→}
