  8→/// <summary>
  9→/// Wraps <see cref="AutomergeDocument"/> to provide CRUD operations
 10→/// for shapes and layers on a collaborative canvas.
 11→/// </summary>
 12→/// <remarks>
 13→/// Document schema:
 14→/// <code>
 15→/// root (map)
 16→///   └── "layers" (list)
 17→///         └── [0..n] (map)
 18→///               ├── "name"      (string)
 19→///               ├── "visible"   (boolean)
 20→///               └── "shapes"    (list)
 21→///                     └── [0..m] (map)
 22→///                           ├── "name"    (string)
 23→///                           ├── "type"    (string)  — "Rectangle" | "Ellipse"
 24→///                           ├── "x"       (f64)
 25→///                           ├── "y"       (f64)
 26→///                           ├── "width"   (f64)
 27→///                           ├── "height"  (f64)
 28→///                           ├── "color"   (string)  — hex "#RRGGBB"
 29→///                           └── "zOrder"  (int64)
 30→/// </code>
 31→/// </remarks>
 32→sealed class AutomergeService : IDisposable
 33→{
 34→  readonly AutomergeDocument _document;
 35→  readonly AutomergeObjectId _layersListId;
 36→  bool _disposed;
 37→
 38→  public AutomergeService()
 39→  {
 40→    _document = AutomergeDocument.Create();
 41→    _layersListId = _document.PutObject(_document.RootId, "layers", AutomergeContainerType.List);
 42→
 43→    // Create a default layer
 44→    var layerId = _document.ListInsertObject(_layersListId, 0, AutomergeContainerType.Map);
 45→    _document.PutString(layerId, "name", "Layer 1");
 46→    _document.PutBoolean(layerId, "visible", true);
 47→    _document.PutObject(layerId, "shapes", AutomergeContainerType.List);
 48→
 49→    _document.Commit("Initialize canvas");
 50→  }
 51→
 52→  AutomergeService(AutomergeDocument document, AutomergeObjectId layersListId)
 53→  {
 54→    _document = document;
 55→    _layersListId = layersListId;
 56→  }
 57→
 58→  /// <summary>
 59→  /// Gets the underlying document for sync operations.
 60→  /// </summary>
 61→  public AutomergeDocument Document => _document;
 62→
 63→  /// <summary>
 64→  /// Adds a shape to the default (first) layer.
 65→  /// </summary>
 66→  public CanvasObject AddShape(string name, ShapeType type, double x, double y, double width, double height, string color)
 67→  {
 68→    ThrowIfDisposed();
 69→    var defaultLayer = _document.ListGetObject(_layersListId, 0)
 70→      ?? throw new InvalidOperationException("No default layer found.");
 71→    var shapesListId = _document.GetObject(defaultLayer, "shapes")
 72→      ?? throw new InvalidOperationException("Default layer has no shapes list.");
 73→
 74→    return AddShapeToLayer(shapesListId, name, type, x, y, width, height, color);
 75→  }
 76→
 77→  /// <summary>
 78→  /// Adds a shape to a specific layer's shapes list.
 79→  /// </summary>
 80→  public CanvasObject AddShapeToLayer(
 81→    AutomergeObjectId shapesListId,
 82→    string name,
 83→    ShapeType type,
 84→    double x,
 85→    double y,
 86→    double width,
 87→    double height,
 88→    string color)
 89→  {
 90→    ThrowIfDisposed();
 91→    ulong index = _document.ListLength(shapesListId);
 92→    var shapeId = _document.ListInsertObject(shapesListId, index, AutomergeContainerType.Map);
 93→    _document.PutString(shapeId, "name", name);
 94→    _document.PutString(shapeId, "type", type.ToString());
 95→    _document.PutDouble(shapeId, "x", x);
 96→    _document.PutDouble(shapeId, "y", y);
 97→    _document.PutDouble(shapeId, "width", width);
 98→    _document.PutDouble(shapeId, "height", height);
 99→    _document.PutString(shapeId, "color", color);
100→    _document.PutInt64(shapeId, "zOrder", (long)index);
101→    _document.Commit($"Add shape: {name}");
102→
103→    return new CanvasObject
104→    {
105→      ObjectId = shapeId,
106→      Name = name,
107→      Type = type,
108→      X = x,
109→      Y = y,
110→      Width = width,
111→      Height = height,
112→      Color = color,
113→      ZOrder = (long)index,
114→    };
115→  }
116→
117→  /// <summary>
118→  /// Moves a shape to a new position.
119→  /// </summary>
120→  public void MoveShape(AutomergeObjectId shapeId, double x, double y)
121→  {
122→    ThrowIfDisposed();
123→    _document.PutDouble(shapeId, "x", x);
124→    _document.PutDouble(shapeId, "y", y);
125→    _document.Commit("Move shape");
126→  }
127→
128→  /// <summary>
129→  /// Resizes a shape.
130→  /// </summary>
131→  public void ResizeShape(AutomergeObjectId shapeId, double width, double height)
132→  {
133→    ThrowIfDisposed();
134→    _document.PutDouble(shapeId, "width", width);
135→    _document.PutDouble(shapeId, "height", height);
136→    _document.Commit("Resize shape");
137→  }
138→
139→  /// <summary>
140→  /// Changes a shape's fill color.
141→  /// </summary>
142→  public void RecolorShape(AutomergeObjectId shapeId, string color)
143→  {
144→    ThrowIfDisposed();
145→    _document.PutString(shapeId, "color", color);
146→    _document.Commit("Recolor shape");
147→  }
148→
149→  /// <summary>
150→  /// Removes a shape from a layer by layer index and shape index.
151→  /// </summary>
152→  public void RemoveShape(ulong layerIndex, ulong shapeIndex)
153→  {
154→    ThrowIfDisposed();
155→    var layerId = _document.ListGetObject(_layersListId, layerIndex)
156→      ?? throw new InvalidOperationException($"No layer at index {layerIndex}.");
157→    var shapesListId = _document.GetObject(layerId, "shapes")
158→      ?? throw new InvalidOperationException("Layer has no shapes list.");
159→
160→    _document.ListRemove(shapesListId, shapeIndex);
161→    _document.Commit($"Remove shape at layer {layerIndex}, index {shapeIndex}");
162→  }
163→
164→  /// <summary>
165→  /// Adds a new layer at the end of the layers list.
166→  /// </summary>
167→  public Layer AddLayer(string name)
168→  {
169→    ThrowIfDisposed();
170→    ulong index = _document.ListLength(_layersListId);
171→    var layerId = _document.ListInsertObject(_layersListId, index, AutomergeContainerType.Map);
172→    _document.PutString(layerId, "name", name);
173→    _document.PutBoolean(layerId, "visible", true);
174→    var shapesListId = _document.PutObject(layerId, "shapes", AutomergeContainerType.List);
175→    _document.Commit($"Add layer: {name}");
176→
177→    return new Layer
178→    {
179→      ObjectId = layerId,
180→      ShapesListId = shapesListId,
181→      Name = name,
182→      IsVisible = true,
183→    };
184→  }
185→
186→  /// <summary>
187→  /// Removes a layer by its index.
188→  /// </summary>
189→  public void RemoveLayer(ulong index)
190→  {
191→    ThrowIfDisposed();
192→    _document.ListRemove(_layersListId, index);
193→    _document.Commit($"Remove layer at {index}");
194→  }
195→
196→  /// <summary>
197→  /// Toggles a layer's visibility.
198→  /// </summary>
199→  public void ToggleLayerVisibility(AutomergeObjectId layerId, bool isVisible)
200→  {
201→    ThrowIfDisposed();
202→    _document.PutBoolean(layerId, "visible", isVisible);
203→    _document.Commit($"Set layer visibility: {isVisible}");
204→  }
205→
206→  /// <summary>
207→  /// Reads the full canvas state from the document.
208→  /// </summary>
209→  public List<Layer> ReadCanvas()
210→  {
211→    ThrowIfDisposed();
212→    var layers = new List<Layer>();
213→    ulong layerCount = _document.ListLength(_layersListId);
214→
215→    for(ulong i = 0; i < layerCount; i++)
216→    {
217→      var layerId = _document.ListGetObject(_layersListId, i);
218→      if(layerId is null)
219→      {
220→        continue;
221→      }
222→
223→      var shapesListId = _document.GetObject(layerId, "shapes");
224→      if(shapesListId is null)
225→      {
226→        continue;
227→      }
228→
229→      var layer = new Layer
230→      {
231→        ObjectId = layerId,
232→        ShapesListId = shapesListId,
233→        Name = _document.GetString(layerId, "name") ?? string.Empty,
234→        IsVisible = _document.GetBoolean(layerId, "visible") ?? true,
235→      };
236→
237→      ulong shapeCount = _document.ListLength(shapesListId);
238→      for(ulong j = 0; j < shapeCount; j++)
239→      {
240→        var shapeId = _document.ListGetObject(shapesListId, j);
241→        if(shapeId is null)
242→        {
243→          continue;
244→        }
245→
246→        string typeStr = _document.GetString(shapeId, "type") ?? "Rectangle";
247→        var shapeType = Enum.TryParse<ShapeType>(typeStr, out var parsed) ? parsed : ShapeType.Rectangle;
248→
249→        layer.Shapes.Add(new CanvasObject
250→        {
251→          ObjectId = shapeId,
252→          Name = _document.GetString(shapeId, "name") ?? string.Empty,
253→          Type = shapeType,
254→          X = _document.GetDouble(shapeId, "x") ?? 0,
255→          Y = _document.GetDouble(shapeId, "y") ?? 0,
256→          Width = _document.GetDouble(shapeId, "width") ?? 0,
257→          Height = _document.GetDouble(shapeId, "height") ?? 0,
258→          Color = _document.GetString(shapeId, "color") ?? "#000000",
259→          ZOrder = _document.GetInt64(shapeId, "zOrder") ?? 0,
260→        });
261→      }
262→
263→      layers.Add(layer);
264→    }
265→
266→    return layers;
267→  }
268→
269→  /// <summary>
270→  /// Saves the full document state as a byte array.
271→  /// </summary>
272→  public byte[] Save()
273→  {
274→    ThrowIfDisposed();
275→    return _document.Save();
276→  }
277→
278→  /// <summary>
279→  /// Loads a canvas from a previously saved byte array.
280→  /// </summary>
281→  public static AutomergeService Load(byte[] data)
282→  {
283→    var doc = AutomergeDocument.Load(data);
284→    var layersListId = doc.GetObject(doc.RootId, "layers")
285→      ?? throw new InvalidOperationException("Saved document does not contain a 'layers' list.");
286→
287→    return new AutomergeService(doc, layersListId);
288→  }
289→
290→  /// <summary>
291→  /// Creates a fork of this service with shared history (for undo or sync).
292→  /// </summary>
293→  public AutomergeService Fork()
294→  {
295→    ThrowIfDisposed();
296→    AutomergeDocument forked = _document.Fork();
297→    return new AutomergeService(forked, _layersListId);
298→  }
299→
300→  /// <summary>
301→  /// Gets the JSON representation of the document.
302→  /// </summary>
303→  public string HydrateJson()
304→  {
305→    ThrowIfDisposed();
306→    return _document.HydrateJson();
307→  }
308→
309→  public void Dispose()
310→  {
311→    if(!_disposed)
312→    {
313→      _disposed = true;
314→      _document.Dispose();
315→    }
316→  }
317→
318→  void ThrowIfDisposed()
319→  {
320→    ObjectDisposedException.ThrowIf(_disposed, this);
321→  }
322→}
