  3→using System.Timers;
  4→using DemoApp.FigmaClone.Models;
  5→using Ray.Automerge;
  6→using Timer = System.Timers.Timer;
  7→
  8→namespace DemoApp.FigmaClone.Services;
  9→
 10→/// <summary>
 11→/// Manages sync state between the local canvas document and a simulated peer document.
 12→/// Uses the Automerge sync protocol (GenerateSyncMessage / ReceiveSyncMessage)
 13→/// on a periodic timer to demonstrate real-time collaborative canvas editing.
 14→/// </summary>
 15→sealed class SyncService : IDisposable
 16→{
 17→  readonly AutomergeService _local;
 18→  readonly AutomergeService _peer;
 19→  readonly AutomergeSyncState _syncLocalToPeer;
 20→  readonly AutomergeSyncState _syncPeerToLocal;
 21→  readonly Timer _syncTimer;
 22→  readonly object _syncLock = new();
 23→  bool _disposed;
 24→
 25→  /// <summary>
 26→  /// Fired after a sync round completes with changes, on the timer thread.
 27→  /// </summary>
 28→  public event Action? SyncCompleted;
 29→
 30→  /// <summary>
 31→  /// Fired when the peer makes a simulated edit, on the timer thread.
 32→  /// </summary>
 33→  public event Action? PeerEdited;
 34→
 35→  public SyncService(AutomergeService local, AutomergeService peer)
 36→  {
 37→    _local = local;
 38→    _peer = peer;
 39→
 40→    _syncLocalToPeer = _local.Document.CreateSyncState();
 41→    _syncPeerToLocal = _peer.Document.CreateSyncState();
 42→
 43→    _syncTimer = new Timer(500);
 44→    _syncTimer.Elapsed += OnSyncTimerElapsed;
 45→    _syncTimer.AutoReset = true;
 46→  }
 47→
 48→  /// <summary>
 49→  /// Gets the number of connected peers (always 1 in this demo).
 50→  /// </summary>
 51→  public int PeerCount => 1;
 52→
 53→  /// <summary>
 54→  /// Gets whether the sync service is actively running.
 55→  /// </summary>
 56→  public bool IsRunning => _syncTimer.Enabled;
 57→
 58→  /// <summary>
 59→  /// Gets the canvas state of the simulated peer document.
 60→  /// </summary>
 61→  public List<Layer> GetPeerCanvas()
 62→  {
 63→    lock(_syncLock)
 64→    {
 65→      return _peer.ReadCanvas();
 66→    }
 67→  }
 68→
 69→  /// <summary>
 70→  /// Starts periodic synchronization between local and peer documents.
 71→  /// </summary>
 72→  public void Start()
 73→  {
 74→    ThrowIfDisposed();
 75→    RunSyncRound();
 76→    _syncTimer.Start();
 77→  }
 78→
 79→  /// <summary>
 80→  /// Stops periodic synchronization.
 81→  /// </summary>
 82→  public void Stop()
 83→  {
 84→    _syncTimer.Stop();
 85→  }
 86→
 87→  /// <summary>
 88→  /// Simulates a remote peer adding a shape to the canvas.
 89→  /// </summary>
 90→  public void SimulatePeerAddShape(
 91→    string name,
 92→    ShapeType type,
 93→    double x,
 94→    double y,
 95→    double width,
 96→    double height,
 97→    string color)
 98→  {
 99→    ThrowIfDisposed();
100→    lock(_syncLock)
101→    {
102→      _peer.AddShape(name, type, x, y, width, height, color);
103→    }
104→
105→    PeerEdited?.Invoke();
106→  }
107→
108→  /// <summary>
109→  /// Simulates a remote peer moving a shape.
110→  /// </summary>
111→  public void SimulatePeerMoveShape(AutomergeObjectId shapeId, double x, double y)
112→  {
113→    ThrowIfDisposed();
114→    lock(_syncLock)
115→    {
116→      _peer.MoveShape(shapeId, x, y);
117→    }
118→
119→    PeerEdited?.Invoke();
120→  }
121→
122→  /// <summary>
123→  /// Runs one round of bidirectional sync (local to peer, peer to local).
124→  /// Returns true if any messages were exchanged.
125→  /// </summary>
126→  public bool RunSyncRound()
127→  {
128→    lock(_syncLock)
129→    {
130→      bool exchanged = false;
131→
132→      for(int i = 0; i < 10; i++)
133→      {
134→        var msgLocalToPeer = _local.Document.GenerateSyncMessage(_syncLocalToPeer);
135→        var msgPeerToLocal = _peer.Document.GenerateSyncMessage(_syncPeerToLocal);
136→
137→        if(msgLocalToPeer is null && msgPeerToLocal is null)
138→        {
139→          break;
140→        }
141→
142→        if(msgLocalToPeer is not null)
143→        {
144→          _peer.Document.ReceiveSyncMessage(_syncPeerToLocal, msgLocalToPeer);
145→          exchanged = true;
146→        }
147→
148→        if(msgPeerToLocal is not null)
149→        {
150→          _local.Document.ReceiveSyncMessage(_syncLocalToPeer, msgPeerToLocal);
151→          exchanged = true;
152→        }
153→      }
154→
155→      if(exchanged)
156→      {
157→        SyncCompleted?.Invoke();
158→      }
159→
160→      return exchanged;
161→    }
162→  }
163→
164→  void OnSyncTimerElapsed(object? sender, ElapsedEventArgs e)
165→  {
166→    if(_disposed)
167→    {
168→      return;
169→    }
170→
171→    RunSyncRound();
172→  }
173→
174→  public void Dispose()
175→  {
176→    if(!_disposed)
177→    {
178→      _disposed = true;
179→      _syncTimer.Stop();
180→      _syncTimer.Dispose();
181→      _syncLocalToPeer.Dispose();
182→      _syncPeerToLocal.Dispose();
183→      _peer.Dispose();
184→    }
185→  }
186→
187→  void ThrowIfDisposed()
188→  {
189→    ObjectDisposedException.ThrowIf(_disposed, this);
190→  }
191→}
