 83→  /// <summary>
 84→  /// Adds a shape at the specified canvas position using the current tool and color.
 85→  /// </summary>
 86→  public void AddShape(double x, double y, double width, double height)
 87→  {
 88→    TakeUndoSnapshot();
 89→    _shapeCounter++;
 90→    string name = $"{_selectedTool} {_shapeCounter}";
 91→    var shape = _service.AddShape(name, _selectedTool, x, y, width, height, _selectedColor);
 92→
 93→    var vm = ToShapeViewModel(shape);
 94→    Shapes.Add(vm);
 95→
 96→    // Also add to the first layer's VM shape list
 97→    if(Layers.Count > 0)
 98→    {
 99→      Layers[0].Shapes.Add(vm);
100→    }
101→
102→    StatusText = $"Added {name}";
103→  }
