111→    {
112→      return;
113→    }
114→
115→    TakeUndoSnapshot();
116→    _service.MoveShape(_selectedShape.ObjectId, x, y);
117→    _selectedShape.X = x;
118→    _selectedShape.Y = y;
119→    StatusText = $"Moved {_selectedShape.Name}";
120→  }
