128→    {
129→      return;
130→    }
131→
132→    TakeUndoSnapshot();
133→    _service.ResizeShape(_selectedShape.ObjectId, width, height);
134→    _selectedShape.Width = width;
135→    _selectedShape.Height = height;
136→    StatusText = $"Resized {_selectedShape.Name}";
