139→  /// <summary>
140→  /// Deletes the currently selected shape.
141→  /// </summary>
142→  public void DeleteSelectedShape()
143→  {
144→    if(_selectedShape is null)
145→    {
146→      return;
147→    }
148→
149→    TakeUndoSnapshot();
150→    int shapeIndex = Shapes.IndexOf(_selectedShape);
151→    if(shapeIndex < 0)
152→    {
153→      return;
154→    }
155→
156→    // Find which layer contains this shape and remove from that layer
157→    int layerIndex = FindLayerIndexForShape(_selectedShape);
158→    if(layerIndex >= 0)
159→    {
160→      int indexInLayer = FindShapeIndexInLayer(layerIndex, _selectedShape);
161→      if(indexInLayer >= 0)
162→      {
163→        _service.RemoveShape((ulong)layerIndex, (ulong)indexInLayer);
164→        Layers[layerIndex].Shapes.Remove(_selectedShape);
165→      }
166→    }
167→
168→    string name = _selectedShape.Name;
169→    Shapes.Remove(_selectedShape);
170→    SelectedShape = null;
171→    StatusText = $"Deleted {name}";
172→  }
