184→    TakeUndoSnapshot();
185→    _service.RecolorShape(_selectedShape.ObjectId, _selectedColor);
186→    _selectedShape.Color = _selectedColor;
187→    StatusText = $"Recolored {_selectedShape.Name}";
188→  }
