190→  void AddLayer()
191→  {
192→    string name = $"Layer {Layers.Count + 1}";
193→    var layer = _service.AddLayer(name);
194→    Layers.Add(ToLayerViewModel(layer));
195→    StatusText = $"Added layer: {name}";
196→  }
197→
198→  void Undo()
199→  {
200→    if(_undoSnapshot is null)
201→    {
202→      StatusText = "Nothing to undo";
203→      return;
204→    }
205→
206→    // The undo snapshot is a fork taken before the last operation.
207→    // We can't replace the service's document directly, so we save/load.
208→    byte[] savedSnapshot = _undoSnapshot.Save();
209→    _undoSnapshot.Dispose();
210→    _undoSnapshot = null;
211→
212→    // Reload the main service from the snapshot
213→    // We need a different approach: use the document's Merge to pull in changes
214→    // Actually, the simplest approach: reload completely
215→    var restored = AutomergeService.Load(savedSnapshot);
216→
217→    // Swap internals by refreshing from the restored state
218→    // Since we can't swap _service (readonly), refresh from restored data
219→    byte[] restoredData = restored.Save();
220→    restored.Dispose();
221→
222→    // Load into a new service and refresh
223→    var newService = AutomergeService.Load(restoredData);
224→    RefreshFromService(newService);
225→    newService.Dispose();
226→
227→    StatusText = "Undone last change";
228→  }
229→
230→  void Save()
231→  {
232→    byte[] saved = _service.Save();
233→    StatusText = $"Saved ({saved.Length} bytes)";
234→  }
235→
236→  void TakeUndoSnapshot()
237→  {
238→    _undoSnapshot?.Dispose();
239→    _undoSnapshot = _service.Fork();
240→  }
241→
242→  void RefreshFromDocument()
243→  {
244→    Shapes.Clear();
245→    Layers.Clear();
246→    var layers = _service.ReadCanvas();
247→    foreach(var layer in layers)
248→    {
249→      var layerVm = ToLayerViewModel(layer);
250→      Layers.Add(layerVm);
251→      foreach(var shapeVm in layerVm.Shapes)
252→      {
253→        Shapes.Add(shapeVm);
254→      }
255→    }
256→  }
257→
258→  void RefreshFromService(AutomergeService service)
259→  {
260→    Shapes.Clear();
261→    Layers.Clear();
262→    _shapeCounter = 0;
263→    var layers = service.ReadCanvas();
264→    foreach(var layer in layers)
265→    {
266→      var layerVm = ToLayerViewModel(layer);
267→      Layers.Add(layerVm);
268→      foreach(var shapeVm in layerVm.Shapes)
269→      {
270→        Shapes.Add(shapeVm);
271→        _shapeCounter++;
272→      }
273→    }
274→
275→    SelectedShape = null;
276→  }
277→
278→  int FindLayerIndexForShape(ShapeViewModel shape)
279→  {
280→    for(int i = 0; i < Layers.Count; i++)
281→    {
282→      if(Layers[i].Shapes.Contains(shape))
283→      {
284→        return i;
285→      }
286→    }
287→
288→    return -1;
289→  }
290→
291→  int FindShapeIndexInLayer(int layerIndex, ShapeViewModel shape)
292→  {
293→    return Layers[layerIndex].Shapes.IndexOf(shape);
294→  }
295→
296→  static LayerViewModel ToLayerViewModel(Layer layer)
297→  {
298→    var vm = new LayerViewModel(layer.ObjectId, layer.ShapesListId, layer.Name, layer.IsVisible);
299→    foreach(var shape in layer.Shapes)
300→    {
301→      vm.Shapes.Add(ToShapeViewModel(shape));
302→    }
303→
304→    return vm;
305→  }
306→
307→  static ShapeViewModel ToShapeViewModel(CanvasObject shape)
308→  {
309→    return new ShapeViewModel(
310→      shape.ObjectId,
311→      shape.Name,
312→      shape.Type,
313→      shape.X,
314→      shape.Y,
315→      shape.Width,
316→      shape.Height,
317→      shape.Color,
318→      shape.ZOrder);
319→  }
320→
321→  public void Dispose()
322→  {
323→    if(!_disposed)
324→    {
325→      _disposed = true;
326→      _undoSnapshot?.Dispose();
327→      _service.Dispose();
328→    }
329→  }
330→}
