 15→
 16→public partial class MainWindow : Window
 17→{
 18→  Canvas? _canvas;
 19→  CanvasViewModel? _viewModel;
 20→
 21→  // Drag state
 22→  bool _isDragging;
 23→  Point _dragStart;
 24→  ShapeViewModel? _dragTarget;
 25→
 26→  // Draw state (click on empty canvas to create shape)
 27→  bool _isDrawing;
 28→  Point _drawStart;
 29→  Border? _drawPreview;
 30→
 31→  // Selection rectangle
 32→  Border? _selectionBorder;
 33→
 34→  // Map from ShapeViewModel to its rendered control
 35→  readonly Dictionary<ShapeViewModel, Control> _shapeControls = [];
 36→
 37→  public MainWindow()
 38→  {
 39→    InitializeComponent();
 40→  }
 41→
 42→  protected override void OnLoaded(RoutedEventArgs e)
 43→  {
 44→    base.OnLoaded(e);
 45→    _canvas = this.FindControl<Canvas>("DrawingCanvas");
 46→    _viewModel = DataContext as CanvasViewModel;
 47→
 48→    if(_viewModel is not null)
 49→    {
 50→      _viewModel.Shapes.CollectionChanged += OnShapesCollectionChanged;
 51→      RenderAllShapes();
 52→    }
 53→  }
 54→
 55→  void OnShapesCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
 56→  {
 57→    if(_canvas is null || _viewModel is null)
 58→    {
 59→      return;
 60→    }
 61→
 62→    switch(e.Action)
 63→    {
 64→      case NotifyCollectionChangedAction.Add:
 65→        if(e.NewItems is not null)
 66→        {
 67→          foreach(ShapeViewModel shape in e.NewItems)
 68→          {
 69→            AddShapeToCanvas(shape);
 70→          }
 71→        }
 72→
 73→        break;
 74→
 75→      case NotifyCollectionChangedAction.Remove:
 76→        if(e.OldItems is not null)
 77→        {
 78→          foreach(ShapeViewModel shape in e.OldItems)
 79→          {
 80→            RemoveShapeFromCanvas(shape);
 81→          }
 82→        }
 83→
 84→        break;
 85→
 86→      case NotifyCollectionChangedAction.Reset:
 87→        ClearAllShapes();
 88→        RenderAllShapes();
 89→        break;
 90→    }
 91→  }
 92→
 93→  void RenderAllShapes()
 94→  {
 95→    if(_viewModel is null)
 96→    {
 97→      return;
 98→    }
 99→
100→    foreach(var shape in _viewModel.Shapes)
101→    {
102→      AddShapeToCanvas(shape);
103→    }
104→  }
105→
106→  void AddShapeToCanvas(ShapeViewModel shape)
107→  {
108→    if(_canvas is null)
109→    {
110→      return;
111→    }
112→
113→    Control shapeControl = CreateShapeControl(shape);
114→    Canvas.SetLeft(shapeControl, shape.X);
115→    Canvas.SetTop(shapeControl, shape.Y);
116→    _canvas.Children.Add(shapeControl);
117→    _shapeControls[shape] = shapeControl;
118→
119→    // Listen for property changes to update rendering
120→    shape.PropertyChanged += (_, args) =>
121→    {
122→      if(args.PropertyName is "X" or "Y")
123→      {
124→        Canvas.SetLeft(shapeControl, shape.X);
125→        Canvas.SetTop(shapeControl, shape.Y);
126→      }
127→      else if(args.PropertyName is "Width" or "Height")
128→      {
129→        shapeControl.Width = shape.Width;
130→        shapeControl.Height = shape.Height;
131→      }
132→      else if(args.PropertyName == "Color")
133→      {
134→        UpdateShapeColor(shapeControl, shape);
135→      }
136→    };
137→  }
138→
139→  Control CreateShapeControl(ShapeViewModel shape)
140→  {
141→    var brush = new SolidColorBrush(Color.Parse(shape.Color));
142→
143→    Control inner;
144→    if(shape.Type == ShapeType.Ellipse)
145→    {
146→      inner = new Ellipse
147→      {
148→        Width = shape.Width,
149→        Height = shape.Height,
150→        Fill = brush,
151→        Stroke = Brushes.Transparent,
152→        StrokeThickness = 2,
153→      };
154→    }
155→    else
156→    {
157→      inner = new Rectangle
158→      {
159→        Width = shape.Width,
160→        Height = shape.Height,
161→        Fill = brush,
162→        Stroke = Brushes.Transparent,
163→        StrokeThickness = 2,
164→        RadiusX = 2,
165→        RadiusY = 2,
166→      };
167→    }
168→
169→    var wrapper = new Border
170→    {
171→      Child = inner,
172→      Tag = shape,
173→      Cursor = new Cursor(StandardCursorType.Hand),
174→    };
175→
176→    wrapper.PointerPressed += OnShapePointerPressed;
177→
178→    return wrapper;
179→  }
180→
181→  void UpdateShapeColor(Control control, ShapeViewModel shape)
182→  {
183→    if(control is Border { Child: Shape avShape })
184→    {
185→      avShape.Fill = new SolidColorBrush(Color.Parse(shape.Color));
186→    }
187→  }
188→
189→  void RemoveShapeFromCanvas(ShapeViewModel shape)
190→  {
191→    if(_canvas is null || !_shapeControls.TryGetValue(shape, out var control))
192→    {
193→      return;
194→    }
195→
196→    _canvas.Children.Remove(control);
197→    _shapeControls.Remove(shape);
198→  }
199→
200→  void ClearAllShapes()
201→  {
202→    if(_canvas is null)
203→    {
204→      return;
205→    }
206→
207→    foreach(var control in _shapeControls.Values)
208→    {
209→      _canvas.Children.Remove(control);
210→    }
211→
212→    _shapeControls.Clear();
213→  }
214→
215→  void UpdateSelectionVisual()
216→  {
217→    if(_canvas is null || _viewModel is null)
218→    {
219→      return;
220→    }
221→
222→    // Remove old selection border
223→    if(_selectionBorder is not null)
224→    {
225→      _canvas.Children.Remove(_selectionBorder);
226→      _selectionBorder = null;
227→    }
228→
229→    // Add selection border around selected shape
230→    if(_viewModel.SelectedShape is not null && _shapeControls.TryGetValue(_viewModel.SelectedShape, out var control))
231→    {
232→      _selectionBorder = new Border
233→      {
234→        Width = _viewModel.SelectedShape.Width + 4,
235→        Height = _viewModel.SelectedShape.Height + 4,
236→        BorderBrush = new SolidColorBrush(Color.Parse("#4A90D9")),
237→        BorderThickness = new Thickness(2),
238→        IsHitTestVisible = false,
239→      };
240→
241→      Canvas.SetLeft(_selectionBorder, _viewModel.SelectedShape.X - 2);
242→      Canvas.SetTop(_selectionBorder, _viewModel.SelectedShape.Y - 2);
243→      _canvas.Children.Add(_selectionBorder);
244→    }
245→  }
246→
247→  // --- Pointer event handlers ---
248→
249→  void OnCanvasPointerPressed(object? sender, PointerPressedEventArgs e)
250→  {
251→    if(_canvas is null || _viewModel is null)
252→    {
253→      return;
254→    }
255→
256→    var point = e.GetPosition(_canvas);
257→
258→    // Deselect current shape if clicking on empty canvas
259→    _viewModel.SelectedShape = null;
260→    UpdateSelectionVisual();
261→
262→    // Start drawing a new shape
263→    _isDrawing = true;
264→    _drawStart = point;
265→
266→    _drawPreview = new Border
267→    {
268→      BorderBrush = new SolidColorBrush(Color.Parse("#999")),
269→      BorderThickness = new Thickness(1),
270→      Background = new SolidColorBrush(Color.Parse(_viewModel.SelectedColor), 0.3),
271→    };
272→
273→    Canvas.SetLeft(_drawPreview, point.X);
274→    Canvas.SetTop(_drawPreview, point.Y);
275→    _canvas.Children.Add(_drawPreview);
276→
277→    e.Handled = true;
278→  }
279→
280→  void OnCanvasPointerMoved(object? sender, PointerEventArgs e)
281→  {
282→    if(_canvas is null || _viewModel is null)
283→    {
284→      return;
285→    }
286→
287→    var point = e.GetPosition(_canvas);
288→
289→    if(_isDragging && _dragTarget is not null)
290→    {
291→      double dx = point.X - _dragStart.X;
292→      double dy = point.Y - _dragStart.Y;
293→      double newX = _dragTarget.X + dx;
294→      double newY = _dragTarget.Y + dy;
295→
296→      // Update VM and visual immediately (commit on release)
297→      _dragTarget.X = newX;
298→      _dragTarget.Y = newY;
299→      _dragStart = point;
300→
301→      // Update selection visual
302→      if(_selectionBorder is not null)
303→      {
304→        Canvas.SetLeft(_selectionBorder, newX - 2);
305→        Canvas.SetTop(_selectionBorder, newY - 2);
306→      }
307→    }
308→    else if(_isDrawing && _drawPreview is not null)
309→    {
310→      double x = Math.Min(_drawStart.X, point.X);
311→      double y = Math.Min(_drawStart.Y, point.Y);
312→      double w = Math.Abs(point.X - _drawStart.X);
313→      double h = Math.Abs(point.Y - _drawStart.Y);
314→
315→      Canvas.SetLeft(_drawPreview, x);
316→      Canvas.SetTop(_drawPreview, y);
317→      _drawPreview.Width = w;
318→      _drawPreview.Height = h;
319→    }
320→  }
321→
322→  void OnCanvasPointerReleased(object? sender, PointerReleasedEventArgs e)
323→  {
324→    if(_canvas is null || _viewModel is null)
325→    {
326→      return;
327→    }
328→
329→    var point = e.GetPosition(_canvas);
330→
331→    if(_isDragging && _dragTarget is not null)
332→    {
333→      // Commit the move to the CRDT
334→      _viewModel.MoveSelectedShape(_dragTarget.X, _dragTarget.Y);
335→      _isDragging = false;
336→      _dragTarget = null;
337→    }
338→    else if(_isDrawing)
339→    {
340→      _isDrawing = false;
341→
342→      // Remove preview
343→      if(_drawPreview is not null)
344→      {
345→        _canvas.Children.Remove(_drawPreview);
346→        _drawPreview = null;
347→      }
348→
349→      double x = Math.Min(_drawStart.X, point.X);
350→      double y = Math.Min(_drawStart.Y, point.Y);
351→      double w = Math.Abs(point.X - _drawStart.X);
352→      double h = Math.Abs(point.Y - _drawStart.Y);
353→
354→      // Minimum size to avoid accidental micro-shapes
355→      if(w < 10)
356→      {
357→        w = 80;
358→      }
359→
360→      if(h < 10)
361→      {
362→        h = 60;
363→      }
364→
365→      _viewModel.AddShape(x, y, w, h);
366→
367→      // Select the newly created shape
368→      if(_viewModel.Shapes.Count > 0)
369→      {
370→        _viewModel.SelectedShape = _viewModel.Shapes[^1];
371→        UpdateSelectionVisual();
372→      }
373→    }
374→  }
375→
376→  void OnShapePointerPressed(object? sender, PointerPressedEventArgs e)
377→  {
378→    if(_canvas is null || _viewModel is null)
379→    {
380→      return;
381→    }
382→
383→    if(sender is Border { Tag: ShapeViewModel shape })
384→    {
385→      _viewModel.SelectedShape = shape;
386→      UpdateSelectionVisual();
387→
388→      // Start dragging
389→      _isDragging = true;
390→      _isDrawing = false;
391→      _dragStart = e.GetPosition(_canvas);
392→      _dragTarget = shape;
393→      e.Handled = true;
394→    }
395→  }
396→
397→  // --- Tool selection ---
398→
399→  void OnRectangleToolClick(object? sender, RoutedEventArgs e)
400→  {
401→    if(_viewModel is null)
402→    {
403→      return;
404→    }
405→
406→    _viewModel.SelectedTool = ShapeType.Rectangle;
407→    var rectTool = this.FindControl<ToggleButton>("RectangleTool");
408→    var ellipseTool = this.FindControl<ToggleButton>("EllipseTool");
409→    if(rectTool is not null)
410→    {
411→      rectTool.IsChecked = true;
412→    }
413→
414→    if(ellipseTool is not null)
415→    {
416→      ellipseTool.IsChecked = false;
417→    }
418→  }
419→
420→  void OnEllipseToolClick(object? sender, RoutedEventArgs e)
421→  {
422→    if(_viewModel is null)
423→    {
424→      return;
425→    }
426→
427→    _viewModel.SelectedTool = ShapeType.Ellipse;
428→    var rectTool = this.FindControl<ToggleButton>("RectangleTool");
429→    var ellipseTool = this.FindControl<ToggleButton>("EllipseTool");
430→    if(rectTool is not null)
431→    {
432→      rectTool.IsChecked = false;
433→    }
434→
435→    if(ellipseTool is not null)
436→    {
437→      ellipseTool.IsChecked = true;
438→    }
439→  }
440→
441→  // --- Color selection ---
442→
443→  void OnColorClick(object? sender, RoutedEventArgs e)
444→  {
445→    if(_viewModel is null || sender is not Button { Tag: string color })
446→    {
447→      return;
448→    }
449→
450→    _viewModel.SelectedColor = color;
451→
452→    // If a shape is selected, recolor it
453→    if(_viewModel.SelectedShape is not null)
454→    {
455→      _viewModel.RecolorSelectedShape();
456→      UpdateSelectionVisual();
457→    }
458→  }
459→}
