  3→using DemoApp.TaskBoard.Models;
  4→using Ray.Automerge;
  5→
  6→namespace DemoApp.TaskBoard.Services;
  7→
  8→/// <summary>
  9→/// Wraps <see cref="AutomergeDocument"/> to provide CRUD operations
 10→/// for columns and tasks on the task board.
 11→/// </summary>
 12→/// <remarks>
 13→/// Document schema:
 14→/// <code>
 15→/// root (map)
 16→///   └── "columns" (list)
 17→///         └── [0..n] (map)
 18→///               ├── "name"   (string)
 19→///               ├── "order"  (int64)
 20→///               └── "tasks"  (list)
 21→///                     └── [0..m] (map)
 22→///                           ├── "title"       (string)
 23→///                           ├── "description" (string)
 24→///                           ├── "status"      (string)
 25→///                           └── "votes"       (counter)
 26→/// </code>
 27→/// </remarks>
 28→sealed class AutomergeService : IDisposable
 29→{
 30→  readonly AutomergeDocument _document;
 31→  readonly AutomergeObjectId _columnsListId;
 32→  bool _disposed;
 33→
 34→  public AutomergeService()
 35→  {
 36→    _document = AutomergeDocument.Create();
 37→    _columnsListId = _document.PutObject(_document.RootId, "columns", AutomergeContainerType.List);
 38→    _document.Commit("Initialize board");
 39→  }
 40→
 41→  AutomergeService(AutomergeDocument document, AutomergeObjectId columnsListId)
 42→  {
 43→    _document = document;
 44→    _columnsListId = columnsListId;
 45→  }
 46→
 47→  /// <summary>
 48→  /// Gets the underlying document for sync operations.
 49→  /// </summary>
 50→  public AutomergeDocument Document => _document;
 51→
 52→  /// <summary>
 53→  /// Adds a new column at the end of the board.
 54→  /// </summary>
 55→  public Column AddColumn(string name)
 56→  {
 57→    ThrowIfDisposed();
 58→    ulong index = _document.ListLength(_columnsListId);
 59→    var columnId = _document.ListInsertObject(_columnsListId, index, AutomergeContainerType.Map);
 60→    _document.PutString(columnId, "name", name);
 61→    _document.PutInt64(columnId, "order", (long)index);
 62→    var tasksListId = _document.PutObject(columnId, "tasks", AutomergeContainerType.List);
 63→    _document.Commit($"Add column: {name}");
 64→
 65→    return new Column
 66→    {
 67→      ObjectId = columnId,
 68→      TasksListId = tasksListId,
 69→      Name = name,
 70→      Order = (long)index,
 71→    };
 72→  }
 73→
 74→  /// <summary>
 75→  /// Removes a column by its index in the columns list.
 76→  /// </summary>
 77→  public void RemoveColumn(ulong index)
 78→  {
 79→    ThrowIfDisposed();
 80→    _document.ListRemove(_columnsListId, index);
 81→    _document.Commit($"Remove column at {index}");
 82→  }
 83→
 84→  /// <summary>
 85→  /// Updates a column's name.
 86→  /// </summary>
 87→  public void UpdateColumnName(AutomergeObjectId columnId, string newName)
 88→  {
 89→    ThrowIfDisposed();
 90→    _document.PutString(columnId, "name", newName);
 91→    _document.Commit($"Rename column to: {newName}");
 92→  }
 93→
 94→  /// <summary>
 95→  /// Adds a new task to the specified column's task list.
 96→  /// </summary>
 97→  public TaskItem AddTask(AutomergeObjectId tasksListId, string title, string description, string status)
 98→  {
 99→    ThrowIfDisposed();
100→    ulong index = _document.ListLength(tasksListId);
101→    var taskId = _document.ListInsertObject(tasksListId, index, AutomergeContainerType.Map);
102→    _document.PutString(taskId, "title", title);
103→    _document.PutString(taskId, "description", description);
104→    _document.PutString(taskId, "status", status);
105→    _document.PutCounter(taskId, "votes", 0);
106→    _document.Commit($"Add task: {title}");
107→
108→    return new TaskItem
109→    {
110→      ObjectId = taskId,
111→      Title = title,
112→      Description = description,
113→      Status = status,
114→      Votes = 0,
115→    };
116→  }
117→
118→  /// <summary>
119→  /// Removes a task by its index from the specified column's task list.
120→  /// </summary>
121→  public void RemoveTask(AutomergeObjectId tasksListId, ulong index)
122→  {
123→    ThrowIfDisposed();
124→    _document.ListRemove(tasksListId, index);
125→    _document.Commit($"Remove task at {index}");
126→  }
127→
128→  /// <summary>
129→  /// Moves a task from one column to another by removing and re-inserting.
130→  /// </summary>
131→  public TaskItem MoveTask(
132→    AutomergeObjectId sourceTasksListId,
133→    ulong sourceIndex,
134→    AutomergeObjectId destTasksListId,
135→    ulong destIndex,
136→    TaskItem task)
137→  {
138→    ThrowIfDisposed();
139→
140→    // Remove from source
141→    _document.ListRemove(sourceTasksListId, sourceIndex);
142→
143→    // Insert into destination as a new map with the same data
144→    var newTaskId = _document.ListInsertObject(destTasksListId, destIndex, AutomergeContainerType.Map);
145→    _document.PutString(newTaskId, "title", task.Title);
146→    _document.PutString(newTaskId, "description", task.Description);
147→    _document.PutString(newTaskId, "status", task.Status);
148→    _document.PutCounter(newTaskId, "votes", task.Votes);
149→    _document.Commit($"Move task: {task.Title}");
150→
151→    return new TaskItem
152→    {
153→      ObjectId = newTaskId,
154→      Title = task.Title,
155→      Description = task.Description,
156→      Status = task.Status,
157→      Votes = task.Votes,
158→    };
159→  }
160→
161→  /// <summary>
162→  /// Increments the vote counter on a task.
163→  /// </summary>
164→  public void IncrementVotes(AutomergeObjectId taskId, long delta = 1)
165→  {
166→    ThrowIfDisposed();
167→    _document.Increment(taskId, "votes", delta);
168→    _document.Commit("Vote");
169→  }
170→
171→  /// <summary>
172→  /// Updates a task's title.
173→  /// </summary>
174→  public void UpdateTaskTitle(AutomergeObjectId taskId, string newTitle)
175→  {
176→    ThrowIfDisposed();
177→    _document.PutString(taskId, "title", newTitle);
178→    _document.Commit($"Update task title: {newTitle}");
179→  }
180→
181→  /// <summary>
182→  /// Updates a task's status.
183→  /// </summary>
184→  public void UpdateTaskStatus(AutomergeObjectId taskId, string newStatus)
185→  {
186→    ThrowIfDisposed();
187→    _document.PutString(taskId, "status", newStatus);
188→    _document.Commit($"Update task status: {newStatus}");
189→  }
190→
191→  /// <summary>
192→  /// Reads the full board state from the document.
193→  /// </summary>
194→  public List<Column> ReadBoard()
195→  {
196→    ThrowIfDisposed();
197→    var columns = new List<Column>();
198→    ulong columnCount = _document.ListLength(_columnsListId);
199→
200→    for(ulong i = 0; i < columnCount; i++)
201→    {
202→      var columnId = _document.ListGetObject(_columnsListId, i);
203→      if(columnId is null)
204→      {
205→        continue;
206→      }
207→
208→      var tasksListId = _document.GetObject(columnId, "tasks");
209→      if(tasksListId is null)
210→      {
211→        continue;
212→      }
213→
214→      var column = new Column
215→      {
216→        ObjectId = columnId,
217→        TasksListId = tasksListId,
218→        Name = _document.GetString(columnId, "name") ?? string.Empty,
219→        Order = _document.GetInt64(columnId, "order") ?? 0,
220→      };
221→
222→      ulong taskCount = _document.ListLength(tasksListId);
223→      for(ulong j = 0; j < taskCount; j++)
224→      {
225→        var taskId = _document.ListGetObject(tasksListId, j);
226→        if(taskId is null)
227→        {
228→          continue;
229→        }
230→
231→        column.Tasks.Add(new TaskItem
232→        {
233→          ObjectId = taskId,
234→          Title = _document.GetString(taskId, "title") ?? string.Empty,
235→          Description = _document.GetString(taskId, "description") ?? string.Empty,
236→          Status = _document.GetString(taskId, "status") ?? string.Empty,
237→          Votes = _document.GetCounter(taskId, "votes") ?? 0,
238→        });
239→      }
240→
241→      columns.Add(column);
242→    }
243→
244→    return columns;
245→  }
246→
247→  /// <summary>
248→  /// Saves the full document state as a byte array.
249→  /// </summary>
250→  public byte[] Save()
251→  {
252→    ThrowIfDisposed();
253→    return _document.Save();
254→  }
255→
256→  /// <summary>
257→  /// Loads a board from a previously saved byte array.
258→  /// </summary>
259→  public static AutomergeService Load(byte[] data)
260→  {
261→    var doc = AutomergeDocument.Load(data);
262→    var columnsListId = doc.GetObject(doc.RootId, "columns")
263→      ?? throw new InvalidOperationException("Saved document does not contain a 'columns' list.");
264→
265→    return new AutomergeService(doc, columnsListId);
266→  }
267→
268→  /// <summary>
269→  /// Gets the JSON representation of the document.
270→  /// </summary>
271→  public string HydrateJson()
272→  {
273→    ThrowIfDisposed();
274→    return _document.HydrateJson();
275→  }
276→
277→  public void Dispose()
278→  {
279→    if(!_disposed)
280→    {
281→      _disposed = true;
282→      _document.Dispose();
283→    }
284→  }
285→
286→  void ThrowIfDisposed()
287→  {
288→    ObjectDisposedException.ThrowIf(_disposed, this);
289→  }
290→}
