  3→using System.Collections.ObjectModel;
  4→using System.Reactive;
  5→using DemoApp.TaskBoard.Models;
  6→using DemoApp.TaskBoard.Services;
  7→using ReactiveUI;
  8→
  9→namespace DemoApp.TaskBoard.ViewModels;
 10→
 11→public class BoardViewModel : ViewModelBase, IDisposable
 12→{
 13→  readonly AutomergeService _service;
 14→  string _statusText = "Ready";
 15→  bool _disposed;
 16→
 17→  public BoardViewModel()
 18→  {
 19→    _service = new AutomergeService();
 20→
 21→    AddColumnCommand = ReactiveCommand.Create(AddColumn);
 22→    SaveCommand = ReactiveCommand.Create(SaveBoard);
 23→
 24→    // Seed default columns
 25→    SeedDefaultColumns();
 26→  }
 27→
 28→  public ObservableCollection<ColumnViewModel> Columns { get; } = [];
 29→
 30→  public string StatusText
 31→  {
 32→    get => _statusText;
 33→    set => this.RaiseAndSetIfChanged(ref _statusText, value);
 34→  }
 35→
 36→  public ReactiveCommand<Unit, Unit> AddColumnCommand { get; }
 37→
 38→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
 39→
 40→  public void AddColumn()
 41→  {
 42→    string name = $"Column {Columns.Count + 1}";
 43→    var column = _service.AddColumn(name);
 44→    Columns.Add(ToColumnViewModel(column));
 45→    StatusText = $"Added column: {name}";
 46→  }
 47→
 48→  public void RemoveColumn(ColumnViewModel columnVm)
 49→  {
 50→    int index = Columns.IndexOf(columnVm);
 51→    if(index < 0)
 52→    {
 53→      return;
 54→    }
 55→
 56→    _service.RemoveColumn((ulong)index);
 57→    Columns.RemoveAt(index);
 58→    StatusText = $"Removed column: {columnVm.Name}";
 59→  }
 60→
 61→  public void AddTask(ColumnViewModel columnVm, string title)
 62→  {
 63→    var task = _service.AddTask(columnVm.TasksListId, title, string.Empty, "todo");
 64→    columnVm.Tasks.Add(ToTaskItemViewModel(task));
 65→    StatusText = $"Added task: {title}";
 66→  }
 67→
 68→  public void RemoveTask(ColumnViewModel columnVm, TaskItemViewModel taskVm)
 69→  {
 70→    int index = columnVm.Tasks.IndexOf(taskVm);
 71→    if(index < 0)
 72→    {
 73→      return;
 74→    }
 75→
 76→    _service.RemoveTask(columnVm.TasksListId, (ulong)index);
 77→    columnVm.Tasks.RemoveAt(index);
 78→    StatusText = $"Removed task: {taskVm.Title}";
 79→  }
 80→
 81→  public void MoveTask(
 82→    ColumnViewModel sourceColumn,
 83→    TaskItemViewModel taskVm,
 84→    ColumnViewModel destColumn,
 85→    int destIndex)
 86→  {
 87→    int sourceIndex = sourceColumn.Tasks.IndexOf(taskVm);
 88→    if(sourceIndex < 0)
 89→    {
 90→      return;
 91→    }
 92→
 93→    var taskModel = new TaskItem
 94→    {
 95→      ObjectId = taskVm.ObjectId,
 96→      Title = taskVm.Title,
 97→      Description = taskVm.Description,
 98→      Status = taskVm.Status,
 99→      Votes = taskVm.Votes,
100→    };
101→
102→    var moved = _service.MoveTask(
103→      sourceColumn.TasksListId,
104→      (ulong)sourceIndex,
105→      destColumn.TasksListId,
106→      (ulong)destIndex,
107→      taskModel);
108→
109→    sourceColumn.Tasks.RemoveAt(sourceIndex);
110→
111→    var movedVm = ToTaskItemViewModel(moved);
112→    destColumn.Tasks.Insert(destIndex, movedVm);
113→    StatusText = $"Moved task: {taskVm.Title}";
114→  }
115→
116→  public void UpvoteTask(TaskItemViewModel taskVm)
117→  {
118→    _service.IncrementVotes(taskVm.ObjectId);
119→    taskVm.Votes++;
120→    StatusText = $"Upvoted: {taskVm.Title} ({taskVm.Votes} votes)";
121→  }
122→
123→  void SaveBoard()
124→  {
125→    byte[] saved = _service.Save();
126→    StatusText = $"Saved ({saved.Length} bytes)";
127→  }
128→
129→  void SeedDefaultColumns()
130→  {
131→    string[] names = ["To Do", "In Progress", "Done"];
132→    foreach(string name in names)
133→    {
134→      var column = _service.AddColumn(name);
135→      Columns.Add(ToColumnViewModel(column));
136→    }
137→
138→    StatusText = "Board initialized with default columns";
139→  }
140→
141→  void RefreshFromDocument()
142→  {
143→    Columns.Clear();
144→    var columns = _service.ReadBoard();
145→    foreach(var column in columns)
146→    {
147→      Columns.Add(ToColumnViewModel(column));
148→    }
149→  }
150→
151→  static ColumnViewModel ToColumnViewModel(Column column)
152→  {
153→    var vm = new ColumnViewModel(column.ObjectId, column.TasksListId, column.Name, column.Order);
154→    foreach(var task in column.Tasks)
155→    {
156→      vm.Tasks.Add(ToTaskItemViewModel(task));
157→    }
158→
159→    return vm;
160→  }
161→
162→  static TaskItemViewModel ToTaskItemViewModel(TaskItem task)
163→  {
164→    return new TaskItemViewModel(task.ObjectId, task.Title, task.Description, task.Status, task.Votes);
165→  }
166→
167→  public void Dispose()
168→  {
169→    if(!_disposed)
170→    {
171→      _disposed = true;
172→      _service.Dispose();
173→    }
174→  }
175→}
