 3→/// <summary>
 4→/// Provides default configuration values for Keycloak integration tests.
 5→/// </summary>
 6→internal static class KeycloakAdminDefaults
 7→{
 8→  /// <summary>
 9→  /// Determines if the specified directory is a solution root directory by checking for .sln or .slnx files.
10→  /// </summary>
11→  /// <param name="directoryPath">The directory path to check.</param>
12→  /// <returns>True if the directory contains solution files, false otherwise.</returns>
13→  public static bool IsSolutionRootDirectory(string directoryPath)
14→  {
15→    var solutionFiles = Directory.GetFiles(directoryPath, "*.sln", SearchOption.TopDirectoryOnly);
16→    var solutionXFiles = Directory.GetFiles(directoryPath, "*.slnx", SearchOption.TopDirectoryOnly);
17→    
18→    return solutionFiles.Length > 0 || solutionXFiles.Length > 0;
19→  }
20→  
21→  
22→  /// <summary>
23→  /// Recursively searches for a file in the specified directory and all its subdirectories.
24→  /// </summary>
25→  /// <param name="directoryPath">The directory path to search in.</param>
26→  /// <param name="fileName">The name of the file to search for.</param>
27→  /// <returns>The absolute path to the file if found, null otherwise.</returns>
28→  public static string? SearchFileRecursively(string directoryPath, string fileName)
29→  {
30→    try
31→    {
32→      // Search in current directory
33→      var filePath = Path.Combine(directoryPath, fileName);
34→      if (File.Exists(filePath))
35→      {
36→        return filePath;
37→      }
38→      
39→      // Search in subdirectories
40→      var subdirectories = Directory.GetDirectories(directoryPath);
41→      foreach (var subdirectory in subdirectories)
42→      {
43→        var foundFilePath = SearchFileRecursively(subdirectory, fileName);
44→        if (foundFilePath is not null)
45→        {
46→          return foundFilePath;
47→        }
48→      }
49→    }
50→    catch (UnauthorizedAccessException)
51→    {
52→      // Skip directories we don't have access to
53→    }
54→    catch (DirectoryNotFoundException)
55→    {
56→      // Skip directories that no longer exist
57→    }
58→    
59→    return null;
60→  }
61→}

