 32→    var adapter1 = new SignalRNetworkAdapter(connectionService1, loggerFactory);
 33→    var receivedMessages1 = new ConcurrentBag<IRepoMessage>();
 34→
 35→    var connectionService2 = TestConnectionServiceFactory.Create(_hubUrl);
 36→    var adapter2 = new SignalRNetworkAdapter(connectionService2, loggerFactory);
 37→    var receivedMessages2 = new ConcurrentBag<IRepoMessage>();
 38→
 39→    var connectionService3 = TestConnectionServiceFactory.Create(_hubUrl);
 40→    var adapter3 = new SignalRNetworkAdapter(connectionService3, loggerFactory);
 41→    var receivedMessages3 = new ConcurrentBag<IRepoMessage>();
 42→
 43→    // Set up message handlers
 44→    adapter1.MessageReceived += (_, args) => receivedMessages1.Add(args.Message);
 45→    adapter2.MessageReceived += (_, args) => receivedMessages2.Add(args.Message);
 46→    adapter3.MessageReceived += (_, args) => receivedMessages3.Add(args.Message);
 47→
