 51→    var peerId3 = PeerId.Generate();
 52→
 53→    adapter1.Connect(peerId1);
 54→    adapter2.Connect(peerId2);
 55→    adapter3.Connect(peerId3);
 56→
 57→    await Task.WhenAll(
 58→      adapter1.WhenReady().WaitAsync(TimeSpan.FromSeconds(5)),
 59→      adapter2.WhenReady().WaitAsync(TimeSpan.FromSeconds(5)),
 60→      adapter3.WhenReady().WaitAsync(TimeSpan.FromSeconds(5))
