/// <summary>
/// Gets the peer ID of this repository.
/// </summary>
public PeerId PeerId => _peerId;

/// <summary>
/// Gets the list of currently connected peers.
/// </summary>
public IReadOnlyList<PeerId> Peers => _network.Peers;

/// <summary>
/// Gets a read-only snapshot of all cached handles.
/// </summary>
public IReadOnlyDictionary<string, IDocHandle> Handles
{
  get
  {
    _handleLock.Wait();
    try
    {
      return new ReadOnlyDictionary<string, IDocHandle>(
        new Dictionary<string, IDocHandle>(_handleCache));
    }
    finally
    {
      _handleLock.Release();
    }
  }
}

#endregion


/// <summary>
/// Initializes a new repository with the specified configuration.
/// </summary>
/// <param name="config">Configuration for the repository.</param>
/// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
public Repo(RepoConfig config)
{
  if(config is null)
    throw new ArgumentNullException(nameof(config));

  // Initialize identity
  _peerId = config.PeerId ?? PeerId.Generate();
  _isEphemeral = config.IsEphemeral;
  _saveDebounceRate = config.SaveDebounceRate;
  _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
  _idFactory = config.IdFactory;

  // Initialize storage subsystem
  if(config.Storage is not null)
  {
    _storage = new StorageSubsystem(config.Storage);
    _storage.DocumentLoaded += OnStorageDocumentLoaded;
    _storage.DocumentSaved += OnStorageDocumentSaved;
  }

  // Initialize network subsystem
  _network = new NetworkSubsystem(config.NetworkAdapters);
  _network.PeerCandidate += OnNetworkPeerCandidate;
  _network.PeerDisconnected += OnNetworkPeerDisconnected;
  _network.MessageReceived += OnNetworkMessageReceived;

  // Initialize synchronizer
  _synchronizer = new CollectionSynchronizer(
    GetDocument,
    UpdateDocument,
    GetPeerMetadata,
    RequestDocument,
    config.Denylist);

  _synchronizer.MessageToSend += OnSynchronizerMessage;
  _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
  _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;

  // Set share and access policies
  if(_shareConfig.Announce is not null)
  {
    _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
  }

  if(_shareConfig.Access is not null)
  {
    _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
  }
}


/// <summary>
/// Disposes the repository and releases all resources.
/// </summary>
public void Dispose()
{
  if(_isDisposed) return;

  _isDisposed = true;

  // Cancel all pending saves
  _saveLock.Wait();

using Ray.Automerge.Repository.Network;
using Ray.Automerge.Repository.Storage;

namespace Ray.Automerge.Repository;

/// <summary>
/// Configuration for creating a Repo instance.
/// </summary>
[PublicAPI]
[ExcludeFromCodeCoverage]
public sealed record RepoConfig
{
  /// <summary>
  /// Unique identifier for this peer. If not specified, a new one will be generated.
  /// </summary>
  public PeerId? PeerId { get; init; }

  /// <summary>
  /// Storage adapter for document persistence. If null, documents are ephemeral.
  /// </summary>
  public IStorageAdapter? Storage { get; init; }

  /// <summary>
  /// Network adapters for peer-to-peer communication. Can be empty for local-only repos.
  /// </summary>
  public IReadOnlyList<INetworkAdapter>? NetworkAdapters { get; init; }

  /// <summary>
  /// If true, sync state will not be persisted even if storage is available.
  /// </summary>
  public bool IsEphemeral { get; init; }

  /// <summary>
  /// Debounce rate for document saves in milliseconds. Default: 100ms.
  /// </summary>
  public int SaveDebounceRate { get; init; } = 100;

  /// <summary>
  /// Share configuration defining which documents to share with which peers.
  /// </summary>
  public ShareConfig? ShareConfig { get; init; }

  /// <summary>
  /// Set of document IDs that should never be synced.
  /// </summary>
  public ISet<string>? Denylist { get; init; }

  /// <summary>
  /// Optional custom document ID factory. If null, uses default UUID-based IDs.
  /// </summary>
  public Func<IReadOnlyList<string>, Task<byte[]>>? IdFactory { get; init; }
}

